output:
200	 *   This function is called from the normal tasking context.
201	 *
202	 ****************************************************************************/
203	
204	int arp_send(in_addr_t ipaddr)
205	{
206	  FAR struct net_driver_s *dev;
207	  FAR struct arp_send_info_s *info;
208	  FAR struct arp_send_s *state;
209	  FAR struct arp_notify_s *notify;
210	  bool sending = false;
211	  int ret;
212	
213	  /* First check if destination is a local broadcast. */
214	
215	  if (ipaddr == INADDR_BROADCAST)
216	    {
217	      /* We don't need to send the ARP request */
218	
219	      return OK;
220	    }
221	
222	#ifdef CONFIG_NET_IGMP
223	  /* Check if the destination address is a multicast address
224	   *
225	   * - IPv4: multicast addresses lie in the class D group -- The address
226	   *   range 224.0.0.0 to 239.255.255.255 (224.0.0.0/4)
227	   *
228	   * - IPv6 multicast addresses are have the high-order octet of the
229	   *   addresses=0xff (ff00::/8.)
230	   */
231	
232	  if (NTOHL(ipaddr) >= 0xe0000000 && NTOHL(ipaddr) <= 0xefffffff)
233	    {
234	      /* We don't need to send the ARP request */
235	
236	      return OK;
237	    }
238	#endif
239	
240	  /* Get the device that can route this request */
241	
242	  dev = netdev_findby_ripv4addr(INADDR_ANY, ipaddr);
243	  if (!dev)
244	    {
245	      nerr("ERROR: Unreachable: %08lx\n", (unsigned long)ipaddr);
246	      return -EHOSTUNREACH;
247	    }
248	
249	  /* ARP support is only built if the Ethernet link layer is supported.
250	   * Continue and send the ARP request only if this device uses the
251	   * Ethernet link layer protocol.
252	   */
253	
254	  if (dev->d_lltype != NET_LL_ETHERNET &&
255	      dev->d_lltype != NET_LL_IEEE80211)
256	    {
257	      return OK;
258	    }
259	
260	  /* Check if the destination address is on the local network. */
261	
262	  if (!net_ipv4addr_maskcmp(ipaddr, dev->d_ipaddr, dev->d_netmask))
263	    {
264	      in_addr_t dripaddr;
265	
266	      /* Destination address is not on the local network */
267	
268	#ifdef CONFIG_NET_ROUTE
269	      /* We have a routing table.. find the correct router to use in
270	       * this case (or, as a fall-back, use the device's default router
271	       * address).  We will use the router IP address instead of the
272	       * destination address when determining the MAC address.
273	       */
274	
275	      netdev_ipv4_router(dev, ipaddr, &dripaddr);
276	#else
277	      /* Use the device's default router IP address instead of the
278	       * destination address when determining the MAC address.
279	       */
280	
281	      net_ipv4addr_copy(dripaddr, dev->d_draddr);
282	#endif
283	      ipaddr = dripaddr;
284	      if (ipaddr == INADDR_ANY)
285	        {
286	          return -EHOSTUNREACH;
287	        }
288	    }
289	
290	  /* The destination address is on the local network.  Check if it is
291	   * the sub-net broadcast address.
292	   */
293	
294	  else if (net_ipv4addr_broadcast(ipaddr, dev->d_netmask))
295	    {
296	      /* Yes.. We don't need to send the ARP request */
297	
298	      return OK;
299	    }
300	
301	  /* No ARP packet if this device do not support ARP */
302	
303	  if (IFF_IS_NOARP(dev->d_flags))
304	    {
305	      ninfo("ARP not supported on %s, no send!\n", dev->d_ifname);
306	      return OK;
307	    }
308	
309	  /* Allocate resources to receive a callback.  This and the following
310	   * initialization is performed with the network lock because we don't
311	   * want anything to happen until we are ready.
312	   */
313	
314	  info = mempool_zallocate(&g_arp_send_infos, UINT_MAX);
315	  if (info == NULL)
316	    {
317	      nerr("ERROR: Failed to allocate ARP send info\n");
318	      return -ENOMEM;
319	    }

140	  int ret;
141	
142	  /* ARP support is only built if the Ethernet link layer is supported.
143	   * Continue and send the ARP request only if this device uses the
144	   * Ethernet link layer protocol.
145	   */
146	
147	  if (dev->d_lltype != NET_LL_ETHERNET &&
148	      dev->d_lltype != NET_LL_IEEE80211)
149	    {
150	      return;
151	    }
152	
153	  /* Find the destination IP address in the ARP table and construct
154	   * the Ethernet header. If the destination IP address isn't on the
155	   * local network, we use the default router's IP address instead.
156	   *
157	   * If not ARP table entry is found, we overwrite the original IP
158	   * packet with an ARP request for the IP address.
159	   */
160	
161	  /* First check if destination is a local broadcast. */
162	
163	  if (net_ipv4addr_hdrcmp(pip->eh_destipaddr, g_broadcast_ipaddr))
164	    {
165	      memcpy(peth->dest,
166	             g_broadcast_ethaddr.ether_addr_octet,
167	             ETHER_ADDR_LEN);
168	      goto finish_header;
169	    }
170	
171	#ifdef CONFIG_NET_IGMP
172	  /* Check if the destination address is a multicast address
173	   *
174	   * - IPv4:
175	   *   multicast addresses lie in the class D group -- The address range
176	   *   224.0.0.0 to 239.255.255.255 (224.0.0.0/4)
177	   *
178	   * - IPv6 multicast addresses are have the high-order octet of the
179	   *   addresses=0xff (ff00::/8.)
180	   */
181	
182	  if (NTOHS(pip->eh_destipaddr[0]) >= 0xe000 &&
183	      NTOHS(pip->eh_destipaddr[0]) <= 0xefff)
184	    {
185	      /* Build the well-known IPv4 IGMP Ethernet address.  The first
186	       * three bytes are fixed; the final three variable come from the
187	       * last three bytes of the IPv4 address (network order).
188	       *
189	       * Address range : 01:00:5e:00:00:00 to 01:00:5e:7f:ff:ff
190	       */
191	
192	      FAR const uint8_t *ip = (FAR uint8_t *)pip->eh_destipaddr;
193	
194	      peth->dest[0] = g_multicast_ethaddr[0];
195	      peth->dest[1] = g_multicast_ethaddr[1];
196	      peth->dest[2] = g_multicast_ethaddr[2];
197	      peth->dest[3] = ip[1] & 0x7f;
198	      peth->dest[4] = ip[2];
199	      peth->dest[5] = ip[3];
200	
201	      goto finish_header;
202	    }
203	#endif
204	
205	  /* Check if the destination address is on the local network. */
206	
207	  destipaddr = net_ip4addr_conv32(pip->eh_destipaddr);
208	  if (!net_ipv4addr_maskcmp(destipaddr, dev->d_ipaddr, dev->d_netmask))
209	    {
210	      /* Destination address is not on the local network */
211	
212	#ifdef CONFIG_NET_ROUTE
213	      /* We have a routing table.. find the correct router to use in
214	       * this case (or, as a fall-back, use the device's default router
215	       * address).  We will use the router IP address instead of the
216	       * destination address when determining the MAC address.
217	       */
218	
219	      netdev_ipv4_router(dev, destipaddr, &ipaddr);
220	#else
221	      /* Use the device's default router IP address instead of the
222	       * destination address when determining the MAC address.
223	       */
224	
225	      net_ipv4addr_copy(ipaddr, dev->d_draddr);
226	#endif
227	
228	      if (ipaddr == INADDR_ANY)
229	        {
230	          dev->d_len = 0;
231	          return;
232	        }
233	    }
234	
235	  /* The destination address is on the local network.  Check if it is
236	   * the sub-net broadcast address.
237	   */
238	
239	  else if (net_ipv4addr_broadcast(destipaddr, dev->d_netmask))
240	    {
241	      /* Yes.. then we won't need to know the destination MAC address */
242	
243	      memcpy(peth->dest,
244	             g_broadcast_ethaddr.ether_addr_octet,
245	             ETHER_ADDR_LEN);
246	      goto finish_header;
247	    }
248	  else
249	    {
250	      /* Else, we use the destination IP address. */
251	
252	      net_ipv4addr_copy(ipaddr, destipaddr);
253	    }
254	
255	  /* Check if we already have this destination address in the ARP table */
256	
257	  ret = arp_find(ipaddr, ethaddr.ether_addr_octet, dev);
258	  if (ret < 0)
259	    {
260	      /* No send ARP if the interface forbiden */
261	
262	      if (IFF_IS_NOARP(dev->d_flags) || ret == -ENETUNREACH)
263	        {
264	          ninfo("ARP not supported on %s, no send!\n", dev->d_ifname);
265	          dev->d_len = 0;
266	          return;
267	        }
268	
269	      ninfo("ARP request for IP %08lx\n", (unsigned long)ipaddr);
270	
271	      if (ret == -EINPROGRESS)
272	        {
273	          /* The destination address was not in our ARP table, and
274	           * the last arp request is in progress, directly drop the packet
275	           * to prevent arp flood.
276	           */
277	
278	#ifdef CONFIG_NET_ARP_SEND_QUEUE
279	          arp_queue_iob(dev, ipaddr, dev->d_iob);
280	          netdev_iob_clear(dev);
281	#else
282	          dev->d_len = 0;
283	#endif
284	          return;
285	        }
286	
287	      /* MAC address marked with all zeros to limit concurrent task
288	       * send ARP request for same destination.
289	       */
290	
291	      arp_update(dev, ipaddr, NULL, 0);
292	#ifdef CONFIG_NET_ARP_SEND_QUEUE
293	      arp_queue_iob(dev, ipaddr, dev->d_iob);
294	      netdev_iob_clear(dev);
295	#endif
296	
297	      /* The destination address was not in our ARP table, so we overwrite
298	       * the IP packet with an ARP request.
299	       */
300	
301	      arp_format(dev, ipaddr);
302	      arp_dump(ARPBUF);
303	      return;
304	    }
305	
306	  /* Build an Ethernet header. */
307	
308	  memcpy(peth->dest, ethaddr.ether_addr_octet, ETHER_ADDR_LEN);
309	
310	  /* Finish populating the Ethernet header */
311	
312	finish_header:
313	  memcpy(peth->src, dev->d_mac.ether.ether_addr_octet, ETHER_ADDR_LEN);
314	  peth->type  = HTONS(ETHTYPE_IP);
315	  dev->d_len += ETH_HDRLEN;
316	}
317	
318	#endif /* CONFIG_NET_ARP */
319

800	
801	  /* Start RX DMA */
802	
803	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
804	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
805	}
