997	/****************************************************************************
998	 * Name: netdriver_ifup
999	 *
1000	 * Description:
1001	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1002	 *
1003	 ****************************************************************************/
1004	
1005	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1006	{
1007	  FAR struct sg2000_eth_priv_s *priv =
1008	      (FAR struct sg2000_eth_priv_s *)dev;
1009	  int ret;
1010	
1011	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1012	
1013	  /* Ensure GMAC clocks and resets are configured */
1014	
1015	  gmac_clock_enable();
1016	
1017	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1018	
1019	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1020	
1021	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1022	  up_mdelay(10);
1023	
1024	  ret = mdio_verify_phy(priv->gmac_base);
1025	  if (ret < 0)
1026	    {
1027	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1028	      return ret;
1029	    }

1100	
1101	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1102	  putreg32(v & ~DMA_RX_SR,
1103	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1104	
1105	  /* Disable MAC TX/RX */
1106	
1107	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1108	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1109	           priv->gmac_base + GMAC_CONFIG);
1110	
1111	  netdev_lower_carrier_off(dev);
1112	
1113	  ninfo("netdriver_ifdown: interface down\n");
1114	
1115	  return OK;
1116	}
