1118	/****************************************************************************
1119	 * Name: netdriver_transmit
1120	 *
1121	 * Description:
1122	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1123	 *   The driver takes ownership of the netpkt and MUST free it after TX
1124	 *   completion (or on error).
1125	 *
1126	 *   Returned Value:
1127	 *     OK on success (pkt queued for TX); negated errno on failure.
1128	 *
1129	 ****************************************************************************/
1130	
1131	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1132	                               FAR netpkt_t *pkt)
1133	{
1134	  FAR struct sg2000_eth_priv_s *priv =
1135	      (FAR struct sg2000_eth_priv_s *)dev;
1136	  unsigned int len = netpkt_getdatalen(dev, pkt);
1137	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1138	  const uint8_t *data;
1139	  int ret;
1140	
1141	  if (len > SG2000_ETH_BUFSIZE)
1142	    {
1143	      nerr("ERROR: TX packet too large: %u\n", len);
1144	      netpkt_free(dev, pkt, NETPKT_TX);
1145	      return -E2BIG;
1146	    }
1147	
1148	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1149	
1150	  if (netpkt_is_fragmented(pkt))
1151	    {
1152	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1153	      data = tmp_buf;
1154	    }
1155	  else
1156	    {
1157	      data = netpkt_getdata(dev, pkt);
1158	      if (!data)
1159	        {
1160	          nerr("ERROR: netpkt_getdata returned NULL\n");
1161	          netpkt_free(dev, pkt, NETPKT_TX);
1162	          return -EINVAL;
1163	        }
1164	    }
1165	
1166	  /* Send via DMA */
1167	
1168	  ret = hw_transmit(priv, data, len);
1169	  if (ret < 0)
1170	    {
1171	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1172	      netpkt_free(dev, pkt, NETPKT_TX);
1173	      return ret;
1174	    }
1175	
1176	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1177	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1178	   */
1179	
1180	  {
1181	    irqstate_t flags = up_irq_save();
1182	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1183	
1184	    priv->tx_pkt[slot] = pkt;
1185	    up_irq_restore(flags);
1186	  }
1187	
1188	  return OK;
1189	}
1190	
1191	/****************************************************************************
1192	 * Name: netdriver_receive
1193	 *
1194	 * Description:
1195	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1196	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1197	 *   NULL if no more packets are available.
1198	 *
1199	 *   Returned Value:

660	static int alloc_dma(struct sg2000_eth_priv_s *priv)
661	{
662	  int i;
663	
664	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
665	                                sizeof(struct sg2000_dma_desc_s));
666	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
667	                                sizeof(struct sg2000_dma_desc_s));
668	
669	  if (!priv->tx_desc || !priv->rx_desc)
670	    {
671	      return -ENOMEM;
672	    }
673	
674	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
676	
677	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
678	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
679	   */
680	
681	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
682	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
683	
684	  for (i = 0; i < TX_RING_SIZE; i++)
685	    {
686	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
687	      if (!priv->tx_buf[i])
688	        {
689	          return -ENOMEM;
690	        }
691	
692	      priv->tx_pkt[i] = NULL;
693	    }
694	
695	  for (i = 0; i < RX_RING_SIZE; i++)
696	    {
697	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
698	      if (!priv->rx_buf[i])
699	        {
700	          return -ENOMEM;
701	        }
702	    }
703	
704	  return 0;
705	}
