93	static void reset_assert(unsigned int id)
94	{
95	  unsigned int bank = id / 32;
96	  unsigned int bit = id % 32;
97	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
98	
99	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
100	}
