102	static void reset_deassert(unsigned int id)
103	{
104	  unsigned int bank = id / 32;
105	  unsigned int bit = id % 32;
106	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
107	
108	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
109	}
