111	static void clk_reset_deassert(unsigned int id)
112	{
113	  unsigned int bank = id / 32;
114	  unsigned int bit = id % 32;
115	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
116	  uint32_t reg = getreg32(addr);
117	
118	  putreg32(reg | (1u << bit), addr);
119	}
