343	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
344	{
345	  uint32_t apb_id1;
346	  uint32_t apb_id2;
347	
348	  ephy_led_pinmux();
349	
350	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
351	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
352	   * This ONLY releases resets and programs the PHY ID — it does NOT
353	   * run the full analog tuning sequence.  The full tuning (which
354	   * accesses internal pages and starts auto-negotiation) must run
355	   * AFTER the MDIO interface is confirmed operational, just as
356	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
357	   */
358	
359	  /* Select APB interface to access EPHY registers */
360	
361	  putreg32(0x0001, phy_top + 0x4);
362	
363	  /* Release shutdown */
364	
365	  putreg32(0x0900, phy_top);
366	
367	  /* Release dig_rst_n — enables MII register access via APB */
368	
369	  putreg32(0x0904, phy_top);

1025	  if (ret < 0)
1026	    {
1027	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1028	      return ret;
1029	    }
1030	
1031	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1032	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1033	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1034	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1035	
1036	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1037	
1038	  ret = phy_config_init(priv);
1039	  if (ret < 0)
1040	    {
1041	      nerr("ERROR: PHY init failed: %d\n", ret);
1042	      return ret;
1043	    }
1044	
1045	  ret = dma_soft_reset(priv->gmac_base);
1046	  if (ret < 0)
1047	    {
1048	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1049	             "diagnostics: %d\n", ret);
1050	      return ret;
1051	    }
1052	
1053	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1054	    {
1055	      ret = alloc_dma(priv);
1056	      if (ret < 0)
1057	        {
1058	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1059	          return ret;
1060	        }
1061	    }
1062	
1063	  init_desc_and_dma(priv);
1064	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1065	  start_mac_and_dma(priv);
1066	  rx_doorbell(priv);
1067	
1068	  up_enable_irq(priv->irq);
